 function semanticFeedback(area,current){
  const source=L.pages.find(p=>p.index===current);if(!source)return;
  const doc=new DOMParser().parseFromString(source.html,'text/html'),pairs=[];
  const norm=t=>t.replace(/^[\s\d.()]+/,'').replace(/[’‘]/g,"'").replace(/[“”]/g,'"').replace(/\s+/g,' ').trim().toLowerCase();
  for(const p of doc.querySelectorAll('.layer [data-name*="-answer-"] p')){const parts=p.innerHTML.split(/<br\s*\/?\s*>/i);if(parts.length<2)continue;const q=el('div');q.innerHTML=parts.shift();const a=el('div');a.innerHTML=parts.join('<br>');if(q.textContent.length>16&&a.textContent.trim())pairs.push({q:norm(q.textContent),answer:a.textContent.trim()});}
  for(const item of area.querySelectorAll('.ss-item')){if(item.querySelector('.inline-answer-slot,table'))continue;const node=item.querySelector('.ss-node:not(.inline-feedback)'),feedback=item.querySelector('.inline-answer-text');if(!node||!feedback)continue;const q=norm(node.textContent),match=pairs.filter(p=>q===p.q||q.length>24&&p.q.endsWith(q)).sort((a,b)=>b.q.length-a.q.length)[0];if(match)feedback.textContent=match.answer;}
 }
